-- Shared manual overlays and dynamic topics; source evidence stays immutable.
-- 逻辑关联由应用事务检查与锁定。
CREATE TABLE "glean_topic" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "slug" character varying NOT NULL, "name" character varying NOT NULL, "description" text NOT NULL DEFAULT '', "rule" text NOT NULL DEFAULT '', "search_enabled" boolean NOT NULL DEFAULT true, "term_groups" jsonb NOT NULL, "version" bigint NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE TABLE "glean_paper_review" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "paper_id" bigint NOT NULL, "topic" character varying NOT NULL, "status" character varying NOT NULL, "note" text NOT NULL DEFAULT '', "labels" jsonb NOT NULL, "version" bigint NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE TABLE "glean_paper_correction" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "paper_id" bigint NOT NULL, "fields" jsonb NOT NULL, "reason" text NOT NULL DEFAULT '', "version" bigint NOT NULL DEFAULT 1, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE TABLE "glean_catalog_change" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "paper_id" bigint NOT NULL DEFAULT 0, "topic" character varying NOT NULL DEFAULT '', "kind" character varying NOT NULL, "before" jsonb NOT NULL, "after" jsonb NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "glean_topic_slug_key" ON "glean_topic" ("slug");
CREATE UNIQUE INDEX "gleanpaperreview_paper_id_topic" ON "glean_paper_review" ("paper_id", "topic");
CREATE INDEX "gleanpaperreview_topic_status" ON "glean_paper_review" ("topic", "status");
CREATE UNIQUE INDEX "glean_paper_correction_paper_id_key" ON "glean_paper_correction" ("paper_id");
CREATE INDEX "gleancatalogchange_paper_id_id" ON "glean_catalog_change" ("paper_id", "id");
CREATE INDEX "gleancatalogchange_topic_id" ON "glean_catalog_change" ("topic", "id");
